void PEGTransformerFactory::PrepareStatementTransform(PEGTransformer &transformer, GeneratedTransformProcess &process) {
	auto &list_pr = process.parse_result.Cast<ListParseResult>();
	auto &choice_pr = list_pr.Child<ChoiceParseResult>(0);
	auto &choice_result = choice_pr.GetResult();
	process.ReserveChildSlots(1);
	auto child_rule = choice_result.GetRule();
	if (!child_rule) {
		throw InternalException("No transform process registered for rule '%s'", choice_result.name);
	}
	process.PushChild({*child_rule, choice_result}, 0);
}

unique_ptr<TransformResultValue> PEGTransformerFactory::ReduceStatementTransform(PEGTransformer &transformer,
                                                                                 GeneratedTransformProcess &process) {
	auto result = process.TakeResult<unique_ptr<SQLStatement>>(0);
	if (!transformer.named_parameter_map.empty()) {
		result->named_param_map = transformer.named_parameter_map;
	}
	result->has_anonymous_parameters = transformer.has_anonymous_parameters;
	return make_uniq<TypedTransformResult<unique_ptr<SQLStatement>>>(std::move(result));
}

void PEGTransformerFactory::PrepareAlterStatementTransform(PEGTransformer &transformer,
                                                           GeneratedTransformProcess &process) {
	auto &list_pr = process.parse_result.Cast<ListParseResult>();
	process.ReserveChildSlots(1);
	process.PushChild({transformer.GetRule("AlterOptions"), list_pr.GetChild(1)}, 0);
}

unique_ptr<TransformResultValue>
PEGTransformerFactory::ReduceAlterStatementTransform(PEGTransformer &transformer, GeneratedTransformProcess &process) {
	auto alter_options = process.TakeResult<unique_ptr<AlterInfo>>(0);
	auto result = TransformAlterStatement(transformer, std::move(alter_options));
	return make_uniq<TypedTransformResult<unique_ptr<SQLStatement>>>(std::move(result));
}

void PEGTransformerFactory::PrepareAlterOptionsTransform(PEGTransformer &transformer,
                                                         GeneratedTransformProcess &process) {
	auto &list_pr = process.parse_result.Cast<ListParseResult>();
	auto &choice_pr = list_pr.Child<ChoiceParseResult>(0);
	auto &choice_result = choice_pr.GetResult();
	process.ReserveChildSlots(1);
	auto child_rule = choice_result.GetRule();
	auto has_transform_process = child_rule && child_rule->transform_process;
	if (!has_transform_process) {
		throw InternalException("No transform process registered for rule '%s'", choice_result.name);
	}
	process.PushChild({*child_rule, choice_result}, 0);
}

unique_ptr<TransformResultValue>
PEGTransformerFactory::ReduceAlterOptionsTransform(PEGTransformer &transformer, GeneratedTransformProcess &process) {
	auto result = process.TakeResult<unique_ptr<AlterInfo>>(0);
	return make_uniq<TypedTransformResult<unique_ptr<AlterInfo>>>(std::move(result));
}

void PEGTransformerFactory::PrepareAlterTableStmtTransform(PEGTransformer &transformer,
                                                           GeneratedTransformProcess &process) {
	auto &list_pr = process.parse_result.Cast<ListParseResult>();
	auto list_items = ExtractParseResultsFromList(list_pr.GetChild(3));
	auto dynamic_child_count = list_items.size();
	process.ReserveChildSlots(3 + dynamic_child_count - 1);
	for (idx_t i = list_items.size(); i > 0; i--) {
		auto child_idx = i - 1;
		process.PushChild({transformer.GetRule("AlterTableOptions"), list_items[child_idx].get()}, 2 + child_idx);
	}
	process.PushChild({transformer.GetRule("BaseTableName"), list_pr.GetChild(2)}, 1);
	auto &if_exists_opt = list_pr.GetChild(1).Cast<OptionalParseResult>();
	if (if_exists_opt.HasResult()) {
		process.PushChild({transformer.GetRule("IfExists"), if_exists_opt.GetResult()}, 0);
	}
}

unique_ptr<TransformResultValue>
PEGTransformerFactory::ReduceAlterTableStmtTransform(PEGTransformer &transformer, GeneratedTransformProcess &process) {
	auto &list_pr = process.parse_result.Cast<ListParseResult>();
	auto dynamic_list_items = ExtractParseResultsFromList(list_pr.GetChild(3));
	auto dynamic_child_count = dynamic_list_items.size();
	optional<bool> if_exists {};
	if (process.child_results[0]) {
		if_exists = process.TakeResult<bool>(0);
	}
	auto base_table_name = process.TakeResult<unique_ptr<BaseTableRef>>(1);
	vector<unique_ptr<AlterTableInfo>> alter_table_options;
	for (idx_t i = 2; i < 2 + dynamic_child_count; i++) {
		alter_table_options.push_back(process.TakeResult<unique_ptr<AlterTableInfo>>(i));
	}
	auto result =
	    TransformAlterTableStmt(transformer, if_exists, std::move(base_table_name), std::move(alter_table_options));
	return make_uniq<TypedTransformResult<unique_ptr<AlterInfo>>>(std::move(result));
}

void PEGTransformerFactory::PrepareAlterSchemaStmtTransform(PEGTransformer &transformer,
                                                            GeneratedTransformProcess &process) {
	auto &list_pr = process.parse_result.Cast<ListParseResult>();
	process.ReserveChildSlots(3);
	process.PushChild({transformer.GetRule("RenameAlter"), list_pr.GetChild(3)}, 2);
	process.PushChild({transformer.GetRule("QualifiedName"), list_pr.GetChild(2)}, 1);
	auto &if_exists_opt = list_pr.GetChild(1).Cast<OptionalParseResult>();
	if (if_exists_opt.HasResult()) {
		process.PushChild({transformer.GetRule("IfExists"), if_exists_opt.GetResult()}, 0);
	}
}

unique_ptr<TransformResultValue>
PEGTransformerFactory::ReduceAlterSchemaStmtTransform(PEGTransformer &transformer, GeneratedTransformProcess &process) {
	optional<bool> if_exists {};
	if (process.child_results[0]) {
		if_exists = process.TakeResult<bool>(0);
	}
	auto qualified_name = process.TakeResult<QualifiedName>(1);
	auto rename_alter = process.TakeResult<unique_ptr<AlterTableInfo>>(2);
	auto result = TransformAlterSchemaStmt(transformer, if_exists, qualified_name, std::move(rename_alter));
	return make_uniq<TypedTransformResult<unique_ptr<AlterInfo>>>(std::move(result));
}

