void PEGTransformerFactory::PrepareDeleteStatementTransform(PEGTransformer &transformer,
                                                            GeneratedTransformProcess &process) {
	auto &list_pr = process.parse_result.Cast<ListParseResult>();
	process.ReserveChildSlots(5);
	auto &returning_clause_opt = list_pr.GetChild(6).Cast<OptionalParseResult>();
	if (returning_clause_opt.HasResult()) {
		process.PushChild({transformer.GetRule("ReturningClause"), returning_clause_opt.GetResult()}, 4);
	}
	auto &where_clause_opt = list_pr.GetChild(5).Cast<OptionalParseResult>();
	if (where_clause_opt.HasResult()) {
		process.PushChild({transformer.GetRule("WhereClause"), where_clause_opt.GetResult()}, 3);
	}
	auto &delete_using_clause_opt = list_pr.GetChild(4).Cast<OptionalParseResult>();
	if (delete_using_clause_opt.HasResult()) {
		process.PushChild({transformer.GetRule("DeleteUsingClause"), delete_using_clause_opt.GetResult()}, 2);
	}
	process.PushChild({transformer.GetRule("TargetOptAlias"), list_pr.GetChild(3)}, 1);
	auto &with_clause_opt = list_pr.GetChild(0).Cast<OptionalParseResult>();
	if (with_clause_opt.HasResult()) {
		process.PushChild({transformer.GetRule("WithClause"), with_clause_opt.GetResult()}, 0);
	}
}

unique_ptr<TransformResultValue>
PEGTransformerFactory::ReduceDeleteStatementTransform(PEGTransformer &transformer, GeneratedTransformProcess &process) {
	optional<CommonTableExpressionMap> with_clause {};
	if (process.child_results[0]) {
		with_clause = process.TakeResult<CommonTableExpressionMap>(0);
	}
	auto target_opt_alias = process.TakeResult<unique_ptr<BaseTableRef>>(1);
	optional<vector<unique_ptr<TableRef>>> delete_using_clause {};
	if (process.child_results[2]) {
		delete_using_clause = process.TakeResult<vector<unique_ptr<TableRef>>>(2);
	}
	optional<unique_ptr<ParsedExpression>> where_clause {};
	if (process.child_results[3]) {
		where_clause = process.TakeResult<unique_ptr<ParsedExpression>>(3);
	}
	optional<vector<unique_ptr<ParsedExpression>>> returning_clause {};
	if (process.child_results[4]) {
		returning_clause = process.TakeResult<vector<unique_ptr<ParsedExpression>>>(4);
	}
	auto result =
	    TransformDeleteStatement(transformer, std::move(with_clause), std::move(target_opt_alias),
	                             std::move(delete_using_clause), std::move(where_clause), std::move(returning_clause));
	return make_uniq<TypedTransformResult<unique_ptr<SQLStatement>>>(std::move(result));
}

