void PEGTransformerFactory::PrepareSubqueryExpressionTransform(PEGTransformer &transformer,
                                                               GeneratedTransformProcess &process) {
	auto &list_pr = process.parse_result.Cast<ListParseResult>();
	process.ReserveChildSlots(3);
	process.PushChild({transformer.GetRule("SubqueryReference"), list_pr.GetChild(2)}, 2);
	auto &subquery_exists_opt = list_pr.GetChild(1).Cast<OptionalParseResult>();
	if (subquery_exists_opt.HasResult()) {
		process.PushChild({transformer.GetRule("SubqueryExists"), subquery_exists_opt.GetResult()}, 1);
	}
	auto &subquery_not_opt = list_pr.GetChild(0).Cast<OptionalParseResult>();
	if (subquery_not_opt.HasResult()) {
		process.PushChild({transformer.GetRule("SubqueryNot"), subquery_not_opt.GetResult()}, 0);
	}
}

unique_ptr<TransformResultValue>
PEGTransformerFactory::ReduceSubqueryExpressionTransform(PEGTransformer &transformer,
                                                         GeneratedTransformProcess &process) {
	optional<bool> subquery_not {};
	if (process.child_results[0]) {
		subquery_not = process.TakeResult<bool>(0);
	}
	optional<bool> subquery_exists {};
	if (process.child_results[1]) {
		subquery_exists = process.TakeResult<bool>(1);
	}
	auto subquery_reference = process.TakeResult<unique_ptr<TableRef>>(2);
	auto result =
	    TransformSubqueryExpression(transformer, subquery_not, subquery_exists, std::move(subquery_reference));
	return make_uniq<TypedTransformResult<unique_ptr<ParsedExpression>>>(std::move(result));
}

