PEGTransformerFactory::ReduceListComprehensionExpressionTransform(PEGTransformer &transformer,
                                                                  GeneratedTransformProcess &process) {
	auto &list_pr = process.parse_result.Cast<ListParseResult>();
	auto dynamic_list_items = ExtractParseResultsFromList(list_pr.GetChild(3));
	auto dynamic_child_count = dynamic_list_items.size();
	auto expression = process.TakeResult<unique_ptr<ParsedExpression>>(0);
	vector<Identifier> col_id_or_string;
	for (idx_t i = 1; i < 1 + dynamic_child_count; i++) {
		col_id_or_string.push_back(process.TakeResult<Identifier>(i));
	}
	auto expression_1 = process.TakeResult<unique_ptr<ParsedExpression>>(2 + dynamic_child_count - 1);
	optional<unique_ptr<ParsedExpression>> list_comprehension_filter {};
	if (process.child_results[3 + dynamic_child_count - 1]) {
		list_comprehension_filter = process.TakeResult<unique_ptr<ParsedExpression>>(3 + dynamic_child_count - 1);
	}
	auto result = TransformListComprehensionExpression(transformer, std::move(expression), col_id_or_string,
	                                                   std::move(expression_1), std::move(list_comprehension_filter));
	return make_uniq<TypedTransformResult<unique_ptr<ParsedExpression>>>(std::move(result));
}

