void PEGTransformerFactory::PrepareLogicalNotExpressionTransform(PEGTransformer &transformer,
                                                                 GeneratedTransformProcess &process) {
	auto &list_pr = process.parse_result.Cast<ListParseResult>();
	process.ReserveChildSlots(2);
	process.PushChild({transformer.GetRule("IsExpression"), list_pr.GetChild(1)}, 1);
	auto &not_expression_opt = list_pr.GetChild(0).Cast<OptionalParseResult>();
	if (not_expression_opt.HasResult()) {
		process.PushChild({transformer.GetRule("NotExpression"), not_expression_opt.GetResult()}, 0);
	}
}

unique_ptr<TransformResultValue>
PEGTransformerFactory::ReduceLogicalNotExpressionTransform(PEGTransformer &transformer,
                                                           GeneratedTransformProcess &process) {
	optional<vector<bool>> not_expression {};
	if (process.child_results[0]) {
		not_expression = process.TakeResult<vector<bool>>(0);
	}
	auto is_expression = process.TakeResult<unique_ptr<ParsedExpression>>(1);
	auto result = TransformLogicalNotExpression(transformer, std::move(not_expression), std::move(is_expression));
	return make_uniq<TypedTransformResult<unique_ptr<ParsedExpression>>>(std::move(result));
}

void PEGTransformerFactory::PrepareNotExpressionTransform(PEGTransformer &transformer,
                                                          GeneratedTransformProcess &process) {
	auto &list_pr = process.parse_result.Cast<ListParseResult>();
	auto &repeat_pr = list_pr.GetChild(0).Cast<RepeatParseResult>();
	auto repeat_children = repeat_pr.GetChildren();
	auto dynamic_child_count = repeat_children.size();
	process.ReserveChildSlots(1 + dynamic_child_count - 1);
	for (idx_t i = repeat_children.size(); i > 0; i--) {
		auto child_idx = i - 1;
		process.PushChild({transformer.GetRule("NotKeyword"), repeat_children[child_idx].get()}, 0 + child_idx);
	}
}

