void PEGTransformerFactory::PrepareIsDistinctFromExpressionTransform(PEGTransformer &transformer,
                                                                     GeneratedTransformProcess &process) {
	auto &list_pr = process.parse_result.Cast<ListParseResult>();
	auto &repeat_opt = list_pr.GetChild(1).Cast<OptionalParseResult>();
	idx_t dynamic_child_count = 0;
	if (repeat_opt.HasResult()) {
		auto &repeat_pr = repeat_opt.GetResult().Cast<RepeatParseResult>();
		auto repeat_children = repeat_pr.GetChildren();
		dynamic_child_count = repeat_children.size();
		process.ReserveChildSlots(2 + dynamic_child_count - 1);
		for (idx_t i = repeat_children.size(); i > 0; i--) {
			auto child_idx = i - 1;
			process.PushChild({transformer.GetRule("IsDistinctFromTail"), repeat_children[child_idx].get()},
			                  1 + child_idx);
		}
	} else {
		process.ReserveChildSlots(2 - 1);
	}
	process.PushChild({transformer.GetRule("ComparisonExpression"), list_pr.GetChild(0)}, 0);
}

unique_ptr<TransformResultValue>
PEGTransformerFactory::ReduceIsDistinctFromExpressionTransform(PEGTransformer &transformer,
                                                               GeneratedTransformProcess &process) {
	auto &list_pr = process.parse_result.Cast<ListParseResult>();
	idx_t dynamic_child_count = 0;
	auto &dynamic_repeat_opt = list_pr.GetChild(1).Cast<OptionalParseResult>();
	if (dynamic_repeat_opt.HasResult()) {
		auto &dynamic_repeat_pr = dynamic_repeat_opt.GetResult().Cast<RepeatParseResult>();
		auto dynamic_repeat_children = dynamic_repeat_pr.GetChildren();
		dynamic_child_count = dynamic_repeat_children.size();
	}
	auto comparison_expression = process.TakeResult<unique_ptr<ParsedExpression>>(0);
	optional<vector<IsDistinctFromTail>> is_distinct_from_tail {};
	if (dynamic_child_count > 0) {
		vector<IsDistinctFromTail> is_distinct_from_tail_value;
		for (idx_t i = 1; i < 1 + dynamic_child_count; i++) {
			is_distinct_from_tail_value.push_back(process.TakeResult<IsDistinctFromTail>(i));
		}
		is_distinct_from_tail = std::move(is_distinct_from_tail_value);
	}
	auto result = TransformIsDistinctFromExpression(transformer, std::move(comparison_expression),
	                                                std::move(is_distinct_from_tail));
	return make_uniq<TypedTransformResult<unique_ptr<ParsedExpression>>>(std::move(result));
}

void PEGTransformerFactory::PrepareIsDistinctFromTailTransform(PEGTransformer &transformer,
                                                               GeneratedTransformProcess &process) {
	auto &list_pr = process.parse_result.Cast<ListParseResult>();
	process.ReserveChildSlots(2);
	process.PushChild({transformer.GetRule("ComparisonExpression"), list_pr.GetChild(1)}, 1);
	process.PushChild({transformer.GetRule("IsDistinctFromOp"), list_pr.GetChild(0)}, 0);
}

unique_ptr<TransformResultValue>
PEGTransformerFactory::ReduceIsDistinctFromTailTransform(PEGTransformer &transformer,
                                                         GeneratedTransformProcess &process) {
	auto is_distinct_from_op = process.TakeResult<ExpressionType>(0);
	auto comparison_expression = process.TakeResult<unique_ptr<ParsedExpression>>(1);
	auto result = TransformIsDistinctFromTail(transformer, is_distinct_from_op, std::move(comparison_expression));
	return make_uniq<TypedTransformResult<IsDistinctFromTail>>(std::move(result));
}

