void PEGTransformerFactory::PrepareLikeClauseTransform(PEGTransformer &transformer,
                                                       GeneratedTransformProcess &process) {
	auto &list_pr = process.parse_result.Cast<ListParseResult>();
	process.ReserveChildSlots(3);
	auto &escape_clause_opt = list_pr.GetChild(2).Cast<OptionalParseResult>();
	if (escape_clause_opt.HasResult()) {
		process.PushChild({transformer.GetRule("EscapeClause"), escape_clause_opt.GetResult()}, 2);
	}
	process.PushChild({transformer.GetRule("OtherOperatorExpression"), list_pr.GetChild(1)}, 1);
	process.PushChild({transformer.GetRule("LikeVariations"), list_pr.GetChild(0)}, 0);
}

unique_ptr<TransformResultValue> PEGTransformerFactory::ReduceLikeClauseTransform(PEGTransformer &transformer,
                                                                                  GeneratedTransformProcess &process) {
	auto like_variations = process.TakeResult<string>(0);
	auto other_operator_expression = process.TakeResult<unique_ptr<ParsedExpression>>(1);
	optional<unique_ptr<ParsedExpression>> escape_clause {};
	if (process.child_results[2]) {
		escape_clause = process.TakeResult<unique_ptr<ParsedExpression>>(2);
	}
	auto result = TransformLikeClause(transformer, like_variations, std::move(other_operator_expression),
	                                  std::move(escape_clause));
	return make_uniq<TypedTransformResult<unique_ptr<ParsedExpression>>>(std::move(result));
}

