void PEGTransformerFactory::PrepareMethodExpressionArgumentListTransform(PEGTransformer &transformer,
                                                                         GeneratedTransformProcess &process) {
	auto &list_pr = process.parse_result.Cast<ListParseResult>();
	process.ReserveChildSlots(4);
	auto &ignore_or_respect_nulls_opt = list_pr.GetChild(3).Cast<OptionalParseResult>();
	if (ignore_or_respect_nulls_opt.HasResult()) {
		process.PushChild({transformer.GetRule("IgnoreOrRespectNulls"), ignore_or_respect_nulls_opt.GetResult()}, 3);
	}
	auto &order_by_clause_opt = list_pr.GetChild(2).Cast<OptionalParseResult>();
	if (order_by_clause_opt.HasResult()) {
		process.PushChild({transformer.GetRule("OrderByClause"), order_by_clause_opt.GetResult()}, 2);
	}
	auto &method_function_arguments_opt = list_pr.GetChild(1).Cast<OptionalParseResult>();
	if (method_function_arguments_opt.HasResult()) {
		process.PushChild({transformer.GetRule("MethodFunctionArguments"), method_function_arguments_opt.GetResult()},
		                  1);
	}
	auto &distinct_or_all_opt = list_pr.GetChild(0).Cast<OptionalParseResult>();
	if (distinct_or_all_opt.HasResult()) {
		process.PushChild({transformer.GetRule("DistinctOrAll"), distinct_or_all_opt.GetResult()}, 0);
	}
}

unique_ptr<TransformResultValue>
PEGTransformerFactory::ReduceMethodExpressionArgumentListTransform(PEGTransformer &transformer,
                                                                   GeneratedTransformProcess &process) {
	optional<bool> distinct_or_all {};
	if (process.child_results[0]) {
		distinct_or_all = process.TakeResult<bool>(0);
	}
	optional<vector<FunctionArgument>> method_function_arguments {};
	if (process.child_results[1]) {
		method_function_arguments = process.TakeResult<vector<FunctionArgument>>(1);
	}
	optional<vector<OrderByNode>> order_by_clause {};
	if (process.child_results[2]) {
		order_by_clause = process.TakeResult<vector<OrderByNode>>(2);
	}
	optional<bool> ignore_or_respect_nulls {};
	if (process.child_results[3]) {
		ignore_or_respect_nulls = process.TakeResult<bool>(3);
	}
	auto result =
	    TransformMethodExpressionArgumentList(transformer, distinct_or_all, std::move(method_function_arguments),
	                                          std::move(order_by_clause), ignore_or_respect_nulls);
	return make_uniq<TypedTransformResult<MethodArguments>>(std::move(result));
}

