void PEGTransformerFactory::PrepareNearestJoinAliasedTransform(PEGTransformer &transformer,
                                                               GeneratedTransformProcess &process) {
	auto &list_pr = process.parse_result.Cast<ListParseResult>();
	process.ReserveChildSlots(5);
	process.PushChild({transformer.GetRule("Expression"), list_pr.GetChild(8)}, 4);
	process.PushChild({transformer.GetRule("DistanceOrSimilarity"), list_pr.GetChild(7)}, 3);
	auto &approx_or_exact_opt = list_pr.GetChild(3).Cast<OptionalParseResult>();
	if (approx_or_exact_opt.HasResult()) {
		process.PushChild({transformer.GetRule("ApproxOrExact"), approx_or_exact_opt.GetResult()}, 2);
	}
	process.PushChild({transformer.GetRule("TableRef"), list_pr.GetChild(2)}, 1);
	auto &join_type_opt = list_pr.GetChild(0).Cast<OptionalParseResult>();
	if (join_type_opt.HasResult()) {
		process.PushChild({transformer.GetRule("JoinType"), join_type_opt.GetResult()}, 0);
	}
}

unique_ptr<TransformResultValue>
PEGTransformerFactory::ReduceNearestJoinAliasedTransform(PEGTransformer &transformer,
                                                         GeneratedTransformProcess &process) {
	auto &list_pr = process.parse_result.Cast<ListParseResult>();
	optional<JoinType> join_type {};
	if (process.child_results[0]) {
		join_type = process.TakeResult<JoinType>(0);
	}
	auto table_ref = process.TakeResult<unique_ptr<TableRef>>(1);
	optional<bool> approx_or_exact {};
	if (process.child_results[2]) {
		approx_or_exact = process.TakeResult<bool>(2);
	}
	optional<unique_ptr<ParsedExpression>> number_literal {};
	auto &number_literal_opt = list_pr.GetChild(5).Cast<OptionalParseResult>();
	if (number_literal_opt.HasResult()) {
		number_literal = TransformNumberLiteral(transformer, number_literal_opt.GetResult());
	}
	auto distance_or_similarity = process.TakeResult<OrderType>(3);
	auto expression = process.TakeResult<unique_ptr<ParsedExpression>>(4);
	auto result = TransformNearestJoinAliased(transformer, join_type, std::move(table_ref), approx_or_exact,
	                                          std::move(number_literal), distance_or_similarity, std::move(expression));
	return make_uniq<TypedTransformResult<unique_ptr<TableRef>>>(std::move(result));
}

