PEGTransformerFactory::ReduceRegularJoinClauseTransform(PEGTransformer &transformer,
                                                        GeneratedTransformProcess &process) {
	optional<bool> asof {};
	if (process.child_results[0]) {
		asof = process.TakeResult<bool>(0);
	}
	optional<JoinType> join_type {};
	if (process.child_results[1]) {
		join_type = process.TakeResult<JoinType>(1);
	}
	auto table_ref = process.TakeResult<unique_ptr<TableRef>>(2);
	auto join_qualifier = process.TakeResult<JoinQualifier>(3);
	auto result =
	    TransformRegularJoinClause(transformer, asof, join_type, std::move(table_ref), std::move(join_qualifier));
	return make_uniq<TypedTransformResult<unique_ptr<TableRef>>>(std::move(result));
}

