void PEGTransformerFactory::PrepareVariableListTransform(PEGTransformer &transformer,
                                                         GeneratedTransformProcess &process) {
	auto &list_pr = process.parse_result.Cast<ListParseResult>();
	auto list_items = ExtractParseResultsFromList(list_pr.GetChild(0));
	auto dynamic_child_count = list_items.size();
	process.ReserveChildSlots(1 + dynamic_child_count - 1);
	for (idx_t i = list_items.size(); i > 0; i--) {
		auto child_idx = i - 1;
		process.PushChild({transformer.GetRule("Expression"), list_items[child_idx].get()}, 0 + child_idx);
	}
}

unique_ptr<TransformResultValue>
PEGTransformerFactory::ReduceVariableListTransform(PEGTransformer &transformer, GeneratedTransformProcess &process) {
	auto &list_pr = process.parse_result.Cast<ListParseResult>();
	auto dynamic_list_items = ExtractParseResultsFromList(list_pr.GetChild(0));
	auto dynamic_child_count = dynamic_list_items.size();
	vector<unique_ptr<ParsedExpression>> expression;
	for (idx_t i = 0; i < 0 + dynamic_child_count; i++) {
		expression.push_back(process.TakeResult<unique_ptr<ParsedExpression>>(i));
	}
	auto result = TransformVariableList(transformer, std::move(expression));
	return make_uniq<TypedTransformResult<vector<unique_ptr<ParsedExpression>>>>(std::move(result));
}

